// Service worker: makes the app work offline.
//
// precache-manifest.js (generated by scripts/build.mjs) lists every file in the build
// plus a version string derived from their contents. On install we cache all of them,
// then serve everything cache-first. Any change to the build changes the version, so
// the browser installs a fresh worker and the old cache is deleted when it activates.
//
// This file must stay a classic script (no import/export): importScripts() is not
// available in module workers.

interface PrecacheManifest {
  version: string;
  urls: string[];
}

const sw = self as unknown as ServiceWorkerGlobalScope;

importScripts("./precache-manifest.js");
const PRECACHE = (self as unknown as { PRECACHE: PrecacheManifest }).PRECACHE;

const CACHE_PREFIX = "lazymicrowave-";
const CACHE_NAME = `${CACHE_PREFIX}${PRECACHE.version}`;

sw.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE.urls))
      .then(() => sw.skipWaiting()),
  );
});

sw.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map((name) => caches.delete(name)),
      );
      await sw.clients.claim();
    })(),
  );
});

sw.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  if (new URL(request.url).origin !== sw.location.origin) return;
  event.respondWith(respond(request));
});

/**
 * Serves a GET request from the cache, falling back to the network. If the network
 * fails on a page load, serves the cached app shell so the app still opens offline.
 */
async function respond(request: Request): Promise<Response> {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request, { ignoreSearch: true });
  if (cached) return cached;

  try {
    return await fetch(request);
  } catch (error) {
    // Offline and not cached: for page loads, fall back to the app shell.
    if (request.mode === "navigate") {
      const shell = await cache.match("./index.html");
      if (shell) return shell;
    }
    throw error;
  }
}
